func newWorkerRecognition() unsafe.Pointer {
	return unsafe.Pointer(new(workerdiscipline.WorkerRecognition))
}

func newNWorkerRecognition(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]workerdiscipline.WorkerRecognition, n)))
}

func ptrWorkerRecognition(p unsafe.Pointer, c int32) any {
	r := (*workerdiscipline.WorkerRecognition)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.WorkerID))
	case 4:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 5:
		return &r.Title
	case 6:
		return &r.Message
	case 7:
		return &r.OccurredAt
	case 8:
		return (*string)(unsafe.Pointer(&r.AwardedByID))
	case 9:
		return &r.VisibleToWorker
	case 10:
		return &r.Version
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueWorkerRecognition(p unsafe.Pointer, c int32) any {
	r := (*workerdiscipline.WorkerRecognition)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.WorkerID)
	case 4:
		return string(r.Kind)
	case 5:
		return r.Title
	case 6:
		if r.Message == "" {
			return nil
		}
		return r.Message
	case 7:
		return r.OccurredAt
	case 8:
		if r.AwardedByID == "" {
			return nil
		}
		return string(r.AwardedByID)
	case 9:
		return r.VisibleToWorker
	case 10:
		return r.Version
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachWorkerRecognition(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*workerdiscipline.WorkerRecognition)(p)
	switch rel {
	case 0:
		r.Worker = (*worker.Worker)(child)
	case 1:
		r.AwardedBy = (*tenant.User)(child)
	}
}

func beforeCreateWorkerRecognition(ctx context.Context, p unsafe.Pointer) error {
	return (*workerdiscipline.WorkerRecognition)(p).BeforeCreate(ctx)
}

